// src/App.jsx - Supabase version
import { useState, useMemo, useEffect, useCallback } from "react";
import { AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from "recharts";
import { supabase } from "./supabase";

const POSICIONES = [
  { ticker:"OTS2D", tipo:"ON", qty:3613, precio_prom:0.9863, capital:17050.22, precio_actual:1.01, resultado_realizado:429.23, resultado_latente:85.62, intereses:852.11, resultado_total:1366.96, rendimiento:0.0802 },
  { ticker:"IRCLD", tipo:"ON", qty:9982, precio_prom:0.9930, capital:46255.38, precio_actual:1.01, resultado_realizado:301.65, resultado_latente:169.60, intereses:589.93, resultado_total:1061.18, rendimiento:0.0229 },
  { ticker:"CP36D", tipo:"ON", qty:27363, precio_prom:0.9736, capital:36676.25, precio_actual:0.86, resultado_realizado:272.49, resultado_latente:-3107.56, intereses:1311.39, resultado_total:-1523.68, rendimiento:-0.0415 },
  { ticker:"OTS3D", tipo:"ON", qty:27000, precio_prom:1.0008, capital:32026.08, precio_actual:1.01, resultado_realizado:-4.08, resultado_latente:248.00, intereses:2538.12, resultado_total:2782.04, rendimiento:0.0869 },
  { ticker:"ZPC3O", tipo:"ON", qty:5000, precio_prom:1.0201, capital:5100.38, precio_actual:1.0058, resultado_realizado:0, resultado_latente:-71.27, intereses:0, resultado_total:-71.27, rendimiento:-0.0140 },
  { ticker:"PQCSO", tipo:"ON", qty:23047, precio_prom:0.9943, capital:30834.41, precio_actual:0.9943, resultado_realizado:99.52, resultado_latente:0, intereses:1206.55, resultado_total:1306.07, rendimiento:0.0424 },
  { ticker:"RUCAO", tipo:"ON", qty:10000, precio_prom:1.0151, capital:10150.5, precio_actual:1.0151, resultado_realizado:0, resultado_latente:0.5, intereses:0, resultado_total:0.5, rendimiento:0.00005 },
  { ticker:"IRCNO", tipo:"ON", qty:773, precio_prom:1.0150, capital:1799.68, precio_actual:1.0150, resultado_realizado:-9.11, resultado_latente:0, intereses:51.21, resultado_total:42.10, rendimiento:0.0234 },
  { ticker:"DNC3O", tipo:"ON", qty:9548, precio_prom:1.0346, capital:9878.82, precio_actual:1.0346, resultado_realizado:0, resultado_latente:0, intereses:0, resultado_total:0, rendimiento:0 },
  { ticker:"CWC6O", tipo:"ON", qty:10337, precio_prom:0.9906, capital:10239.79, precio_actual:null, resultado_realizado:0, resultado_latente:0, intereses:0, resultado_total:0, rendimiento:0 },
  { ticker:"TLCUD", tipo:"ON", qty:7000, precio_prom:1.0, capital:7000, precio_actual:null, resultado_realizado:0, resultado_latente:0, intereses:0, resultado_total:0, rendimiento:0 },
  { ticker:"EAC3O", tipo:"ON", qty:5000, precio_prom:0.9697, capital:4872.74, precio_actual:0.9697, resultado_realizado:0, resultado_latente:0, intereses:0, resultado_total:0, rendimiento:0 },
  { ticker:"ANF", tipo:"Acción", qty:28, precio_prom:91, capital:2560.74, precio_actual:91, resultado_realizado:0, resultado_latente:0, intereses:0, resultado_total:0, rendimiento:0 },
];
const DB = { patrimonio_total:132810.49, saldo_operar:19518.04, invertido:113292.45, resultado_total:14620.35, rendimiento_promedio:1.41 };
const PIE_COLORS = ["#d4a843","#7c6b2e","#c8a96e","#8b7c4a","#e8d5a3"];
const f$ = n => new Intl.NumberFormat("es-AR",{style:"currency",currency:"USD",minimumFractionDigits:2}).format(n??0);
const fPct = n => `${n>=0?"+":""}${n.toFixed(2)}%`;

export default function App() {
  const [tab,setTab]=useState("dashboard");
  const [search,setSearch]=useState("");
  const [movs,setMovs]=useState([]);
  const [arqs,setArqs]=useState([]);
  const [ldMovs,setLdMovs]=useState(true);
  const [ldArqs,setLdArqs]=useState(true);
  const [showForm,setShowForm]=useState(false);
  const [saving,setSaving]=useState(false);
  const [msg,setMsg]=useState("");
  const [form,setForm]=useState({fecha:"",ticker:"",tipo_activo:"ON",tipo_mov:"Compra",cantidad:"",precio:"",comision:"0",cuenta:"Galicia",comentario:""});

  const fetchMovs=useCallback(async()=>{
    const{data}=await supabase.from("movimientos").select("*").order("fecha",{ascending:true});
    setMovs(data||[]);setLdMovs(false);
  },[]);
  const fetchArqs=useCallback(async()=>{
    const{data}=await supabase.from("arqueos").select("*").order("fecha_guardado",{ascending:true});
    setArqs(data||[]);setLdArqs(false);
  },[]);

  useEffect(()=>{
    fetchMovs();
    const ch=supabase.channel("movs").on("postgres_changes",{event:"*",schema:"public",table:"movimientos"},fetchMovs).subscribe();
    return()=>supabase.removeChannel(ch);
  },[fetchMovs]);
  useEffect(()=>{
    fetchArqs();
    const ch=supabase.channel("arqs").on("postgres_changes",{event:"*",schema:"public",table:"arqueos"},fetchArqs).subscribe();
    return()=>supabase.removeChannel(ch);
  },[fetchArqs]);

  const handleAdd=useCallback(async()=>{
    if(!form.fecha||!form.precio)return;
    setSaving(true);
    const monto_neto=form.tipo_mov==="Compra"?-(parseFloat(form.precio)*(parseFloat(form.cantidad)||1)+parseFloat(form.comision||0)):parseFloat(form.precio);
    const{error}=await supabase.from("movimientos").insert({fecha:form.fecha,ticker:form.ticker||null,tipo_activo:form.tipo_activo||null,tipo_mov:form.tipo_mov,cantidad:parseFloat(form.cantidad)||null,precio:parseFloat(form.precio),comision:parseFloat(form.comision)||0,monto_neto,cuenta:form.cuenta,comentario:form.comentario||null});
    if(error)alert("Error: "+error.message);
    else{setForm({fecha:"",ticker:"",tipo_activo:"ON",tipo_mov:"Compra",cantidad:"",precio:"",comision:"0",cuenta:"Galicia",comentario:""});setShowForm(false);}
    setSaving(false);
  },[form]);

  const handleArqueo=useCallback(async()=>{
    const hoy=new Date();
    const mes=hoy.toLocaleDateString("es-AR",{month:"short",year:"numeric"});
    const id=`${hoy.getFullYear()}-${String(hoy.getMonth()+1).padStart(2,"0")}`;
    const{error}=await supabase.from("arqueos").upsert({id,mes,patrimonio:DB.patrimonio_total,resultado:DB.resultado_total,saldo_efectivo:DB.saldo_operar,invertido:DB.invertido,fecha_guardado:new Date().toISOString()});
    if(error)alert("Error: "+error.message);
    else{setMsg(`✓ Arqueo de ${mes} guardado`);setTimeout(()=>setMsg(""),3000);}
  },[]);

  const posF=useMemo(()=>POSICIONES.filter(p=>p.ticker.toLowerCase().includes(search.toLowerCase())),[search]);
  const movsF=useMemo(()=>[...movs].filter(m=>!search||(m.ticker&&m.ticker.toLowerCase().includes(search.toLowerCase()))).reverse().slice(0,60),[movs,search]);
  const pieData=[{name:"ONs",value:POSICIONES.filter(p=>p.tipo==="ON").reduce((s,p)=>s+p.capital,0)},{name:"Acciones",value:POSICIONES.filter(p=>p.tipo==="Acción").reduce((s,p)=>s+p.capital,0)},{name:"Efectivo",value:DB.saldo_operar}];

  const S={fontFamily:"'Georgia','Times New Roman',serif",background:"#0d0b06",minHeight:"100vh",color:"#f0e6c8"};
  const card={background:"linear-gradient(135deg,#1a1408,#120f05)",border:"1px solid #3a3010",borderRadius:12,padding:"18px 20px"};
  const tbl={background:"#120f05",border:"1px solid #3a3010",borderRadius:12,overflow:"hidden"};
  const inp={background:"#120f05",border:"1px solid #3a3010",color:"#f0e6c8",padding:"8px 12px",borderRadius:8,fontSize:13,outline:"none",width:"100%",boxSizing:"border-box"};
  const lbl={fontSize:11,color:"#8b7c4a",display:"block",marginBottom:4};
  const TH={padding:"12px 14px",textAlign:"right",color:"#8b7c4a",fontSize:11,fontWeight:"normal",textTransform:"uppercase",letterSpacing:"0.07em",borderBottom:"1px solid #2a2010",whiteSpace:"nowrap"};
  const TD=(x={})=>({padding:"11px 14px",textAlign:"right",...x});
  const mc=t=>{if(t==="Compra")return{bg:"#1a2e1a",c:"#7ec87e"};if(t?.includes("Venta"))return{bg:"#2e1a1a",c:"#e87c7c"};if(t==="Depósito")return{bg:"#1a2a1a",c:"#7ec8b0"};if(t==="Extracción")return{bg:"#2a1a1a",c:"#e8a07c"};return{bg:"#1a1a2a",c:"#c8a96e"};};

  return(
    <div style={S}>
      <div style={{background:"linear-gradient(135deg,#1a1408,#0d0b06)",borderBottom:"1px solid #3a3010",padding:"18px 28px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div>
          <div style={{fontSize:20,fontWeight:"bold",color:"#d4a843",letterSpacing:"0.05em"}}>📈 Portfolio</div>
          <div style={{fontSize:11,color:"#8b7c4a",letterSpacing:"0.12em",textTransform:"uppercase",marginTop:2}}>Seguimiento de Inversiones · Supabase ⚡</div>
        </div>
        <div style={{display:"flex",gap:8}}>
          {[["dashboard","Dashboard"],["posiciones","Posiciones"],["movimientos","Movimientos"],["arqueos","Arqueos"]].map(([k,v])=>(
            <button key={k} onClick={()=>setTab(k)} style={{padding:"7px 16px",borderRadius:8,border:tab===k?"1px solid #d4a843":"1px solid #3a3010",background:tab===k?"#2a1f08":"transparent",color:tab===k?"#d4a843":"#8b7c4a",fontSize:13,cursor:"pointer"}}>{v}</button>
          ))}
        </div>
      </div>

      <div style={{padding:"24px 28px",maxWidth:1200,margin:"0 auto"}}>

        {tab==="dashboard"&&(
          <div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:16,marginBottom:24}}>
              {[{label:"Patrimonio Total",value:f$(DB.patrimonio_total),sub:"activos + efectivo",color:"#d4a843"},{label:"Efectivo Disponible",value:f$(DB.saldo_operar),sub:"listo para operar",color:"#7ec87e"},{label:"Capital Invertido",value:f$(DB.invertido),sub:"en posiciones abiertas",color:"#c8a96e"},{label:"Resultado Total",value:f$(DB.resultado_total),sub: fPct(DB.rendimiento_promedio),color:"#7ec87e"}].map((c,i)=>(
                <div key={i} style={card}>
                  <div style={{fontSize:11,color:"#8b7c4a",textTransform:"uppercase",letterSpacing:"0.1em",marginBottom:8}}>{c.label}</div>
                  <div style={{fontSize:24,fontWeight:"bold",color:c.color,marginBottom:4}}>{c.value}</div>
                  <div style={{fontSize:12,color:"#5a4a2a"}}>{c.sub}</div>
                </div>
              ))}
            </div>
            <div style={{display:"grid",gridTemplateColumns:"2fr 1fr",gap:20,marginBottom:20}}>
              <div style={{...tbl,padding:20}}>
                <div style={{fontSize:12,color:"#8b7c4a",marginBottom:14,textTransform:"uppercase",letterSpacing:"0.07em"}}>Patrimonio mensual</div>
                <ResponsiveContainer width="100%" height={200}>
                  <AreaChart data={arqs}>
                    <defs><linearGradient id="g1" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#d4a843" stopOpacity={0.3}/><stop offset="95%" stopColor="#d4a843" stopOpacity={0}/></linearGradient></defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#2a2010"/>
                    <XAxis dataKey="mes" tick={{fill:"#5a4a2a",fontSize:9}}/>
                    <YAxis tick={{fill:"#5a4a2a",fontSize:9}} tickFormatter={v=>`$${(v/1000).toFixed(0)}k`}/>
                    <Tooltip contentStyle={{background:"#1a1408",border:"1px solid #3a3010",borderRadius:8}} formatter={v=>[f$(v),""]}/>
                    <Area type="monotone" dataKey="patrimonio" stroke="#d4a843" fill="url(#g1)" strokeWidth={2}/>
                  </AreaChart>
                </ResponsiveContainer>
              </div>
              <div style={{...tbl,padding:20}}>
                <div style={{fontSize:12,color:"#8b7c4a",marginBottom:14,textTransform:"uppercase",letterSpacing:"0.07em"}}>Distribución</div>
                <ResponsiveContainer width="100%" height={170}>
                  <PieChart>
                    <Pie data={pieData} cx="50%" cy="50%" innerRadius={40} outerRadius={68} dataKey="value" paddingAngle={3}>
                      {pieData.map((_,i)=><Cell key={i} fill={PIE_COLORS[i%PIE_COLORS.length]}/>)}
                    </Pie>
                    <Tooltip contentStyle={{background:"#1a1408",border:"1px solid #3a3010",borderRadius:8}} formatter={v=>[f$(v),""]}/>
                    <Legend formatter={v=><span style={{color:"#c8a96e",fontSize:11}}>{v}</span>}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
            <div style={{...tbl,padding:20}}>
              <div style={{fontSize:12,color:"#8b7c4a",marginBottom:14,textTransform:"uppercase",letterSpacing:"0.07em"}}>Resultado por ticker</div>
              <ResponsiveContainer width="100%" height={160}>
                <BarChart data={POSICIONES.filter(p=>p.resultado_total!==0)}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#2a2010"/>
                  <XAxis dataKey="ticker" tick={{fill:"#5a4a2a",fontSize:9}}/>
                  <YAxis tick={{fill:"#5a4a2a",fontSize:9}} tickFormatter={v=>`$${v.toFixed(0)}`}/>
                  <Tooltip contentStyle={{background:"#1a1408",border:"1px solid #3a3010",borderRadius:8}} formatter={v=>[f$(v),"Resultado"]}/>
                  <Bar dataKey="resultado_total" radius={[4,4,0,0]}>
                    {POSICIONES.filter(p=>p.resultado_total!==0).map((p,i)=><Cell key={i} fill={p.resultado_total>=0?"#7ec87e":"#e87c7c"}/>)}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        {tab==="posiciones"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
              <div style={{fontSize:18,color:"#d4a843"}}>Posiciones Abiertas</div>
              <input placeholder="Buscar ticker..." value={search} onChange={e=>setSearch(e.target.value)} style={{...inp,width:200}}/>
            </div>
            <div style={tbl}>
              <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                <thead><tr style={{background:"#1a1408"}}>
                  {["Ticker","Tipo","Cantidad","P. Prom.","Capital","P. Actual","Res. Real.","Res. Latente","Intereses","Total","Rend."].map(h=><th key={h} style={TH}>{h}</th>)}
                </tr></thead>
                <tbody>
                  {posF.map((p,i)=>(
                    <tr key={i} style={{borderBottom:"1px solid #1a1408",background:i%2===0?"transparent":"#0f0d04"}}>
                      <td style={TD({color:"#d4a843",fontWeight:"bold"})}>{p.ticker}</td>
                      <td style={TD({color:"#c8a96e"})}>{p.tipo}</td>
                      <td style={TD()}>{p.qty.toLocaleString("es-AR")}</td>
                      <td style={TD()}>{p.precio_prom.toFixed(4)}</td>
                      <td style={TD()}>{f$(p.capital)}</td>
                      <td style={TD({color:"#8b7c4a"})}>{p.precio_actual?p.precio_actual.toFixed(4):"—"}</td>
                      <td style={TD({color:p.resultado_realizado>=0?"#7ec87e":"#e87c7c"})}>{f$(p.resultado_realizado)}</td>
                      <td style={TD({color:p.resultado_latente>=0?"#7ec87e":"#e87c7c"})}>{f$(p.resultado_latente)}</td>
                      <td style={TD({color:"#c8a96e"})}>{f$(p.intereses)}</td>
                      <td style={TD({color:p.resultado_total>=0?"#7ec87e":"#e87c7c",fontWeight:"bold"})}>{f$(p.resultado_total)}</td>
                      <td style={TD({color:p.rendimiento>=0?"#7ec87e":"#e87c7c"})}>{ fPct(p.rendimiento*100)}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr style={{background:"#1a1408",borderTop:"1px solid #3a3010"}}>
                    <td colSpan={4} style={TD({color:"#8b7c4a",fontSize:11,textTransform:"uppercase"})}>Total</td>
                    <td style={TD({color:"#d4a843",fontWeight:"bold"})}>{f$(POSICIONES.reduce((s,p)=>s+p.capital,0))}</td>
                    <td/><td style={TD({color:"#7ec87e",fontWeight:"bold"})}>{f$(POSICIONES.reduce((s,p)=>s+p.resultado_realizado,0))}</td>
                    <td style={TD({color:"#7ec87e",fontWeight:"bold"})}>{f$(POSICIONES.reduce((s,p)=>s+p.resultado_latente,0))}</td>
                    <td style={TD({color:"#c8a96e",fontWeight:"bold"})}>{f$(POSICIONES.reduce((s,p)=>s+p.intereses,0))}</td>
                    <td style={TD({color:"#7ec87e",fontWeight:"bold"})}>{f$(POSICIONES.reduce((s,p)=>s+p.resultado_total,0))}</td>
                    <td/>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        )}

        {tab==="movimientos"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
              <div>
                <div style={{fontSize:18,color:"#d4a843"}}>Historial de Movimientos</div>
                {!ldMovs&&<div style={{fontSize:11,color:"#5a4a2a",marginTop:2}}>{movs.length} movimientos · Supabase ⚡</div>}
              </div>
              <div style={{display:"flex",gap:10}}>
                <input placeholder="Buscar ticker..." value={search} onChange={e=>setSearch(e.target.value)} style={{...inp,width:180}}/>
                <button onClick={()=>setShowForm(!showForm)} style={{background:"#2a1f08",border:"1px solid #d4a843",color:"#d4a843",padding:"8px 18px",borderRadius:8,fontSize:13,cursor:"pointer"}}>{showForm?"✕ Cancelar":"+ Nuevo"}</button>
              </div>
            </div>

            {showForm&&(
              <div style={{background:"#1a1408",border:"1px solid #3a3010",borderRadius:12,padding:20,marginBottom:20}}>
                <div style={{fontSize:14,color:"#d4a843",marginBottom:16}}>Registrar Movimiento</div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12,marginBottom:12}}>
                  <div><label style={lbl}>Fecha</label><input type="date" value={form.fecha} onChange={e=>setForm(p=>({...p,fecha:e.target.value}))} style={inp}/></div>
                  <div><label style={lbl}>Ticker</label><input value={form.ticker} onChange={e=>setForm(p=>({...p,ticker:e.target.value.toUpperCase()}))} placeholder="ej: AL30D" style={inp}/></div>
                  <div><label style={lbl}>Tipo Activo</label><select value={form.tipo_activo} onChange={e=>setForm(p=>({...p,tipo_activo:e.target.value}))} style={inp}><option>ON</option><option>Bono</option><option>Acción</option></select></div>
                  <div><label style={lbl}>Movimiento</label><select value={form.tipo_mov} onChange={e=>setForm(p=>({...p,tipo_mov:e.target.value}))} style={inp}><option>Compra</option><option>Venta</option><option>Venta parcial</option><option>Cupón / interés</option><option>Depósito</option><option>Extracción</option></select></div>
                </div>
                <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:12,marginBottom:14}}>
                  <div><label style={lbl}>Cantidad</label><input type="number" value={form.cantidad} onChange={e=>setForm(p=>({...p,cantidad:e.target.value}))} style={inp}/></div>
                  <div><label style={lbl}>Precio / Monto</label><input type="number" value={form.precio} onChange={e=>setForm(p=>({...p,precio:e.target.value}))} style={inp}/></div>
                  <div><label style={lbl}>Comisión</label><input type="number" value={form.comision} onChange={e=>setForm(p=>({...p,comision:e.target.value}))} style={inp}/></div>
                  <div><label style={lbl}>Cuenta</label><select value={form.cuenta} onChange={e=>setForm(p=>({...p,cuenta:e.target.value}))} style={inp}><option>Galicia</option><option>Balanz</option><option>Balanz CCL</option></select></div>
                </div>
                <div style={{display:"flex",gap:10}}>
                  <input value={form.comentario} onChange={e=>setForm(p=>({...p,comentario:e.target.value}))} placeholder="Comentario (opcional)" style={{...inp,flex:1}}/>
                  <button onClick={handleAdd} disabled={saving} style={{background:saving?"#5a4a2a":"#d4a843",color:"#0d0b06",padding:"8px 24px",borderRadius:8,fontSize:13,fontWeight:"bold",cursor:"pointer",border:"none",minWidth:100}}>{saving?"Guardando...":"Guardar"}</button>
                </div>
              </div>
            )}

            {ldMovs?<div style={{textAlign:"center",padding:60,color:"#8b7c4a"}}>Cargando... ⚡</div>:(
              <div style={tbl}>
                <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                  <thead><tr style={{background:"#1a1408"}}>{["Fecha","Ticker","Tipo","Movimiento","Cantidad","Precio","Comisión","Monto Neto","Cuenta","Comentario"].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
                  <tbody>
                    {movsF.length===0?<tr><td colSpan={10} style={{textAlign:"center",padding:40,color:"#5a4a2a"}}>No hay movimientos. ¡Agregá el primero!</td></tr>:
                    movsF.map((m,i)=>{const{bg,c}=mc(m.tipo_mov);return(
                      <tr key={m.id||i} style={{borderBottom:"1px solid #1a1408",background:i%2===0?"transparent":"#0f0d04"}}>
                        <td style={TD({color:"#8b7c4a",whiteSpace:"nowrap"})}>{m.fecha}</td>
                        <td style={TD({color:"#d4a843",fontWeight:"bold"})}>{m.ticker||"—"}</td>
                        <td style={TD({color:"#c8a96e"})}>{m.tipo_activo||"—"}</td>
                        <td style={TD()}><span style={{padding:"2px 8px",borderRadius:4,fontSize:11,background:bg,color:c}}>{m.tipo_mov}</span></td>
                        <td style={TD()}>{m.cantidad?Number(m.cantidad).toLocaleString("es-AR"):"—"}</td>
                        <td style={TD()}>{m.precio?Number(m.precio).toLocaleString("es-AR",{minimumFractionDigits:2,maximumFractionDigits:6}):"—"}</td>
                        <td style={TD({color:"#8b7c4a"})}>{m.comision?f$(m.comision):"—"}</td>
                        <td style={TD({fontWeight:"bold",color:m.monto_neto>=0?"#7ec87e":"#e87c7c"})}>{f$(m.monto_neto)}</td>
                        <td style={TD({color:"#c8a96e"})}>{m.cuenta}</td>
                        <td style={TD({color:"#5a4a2a",fontSize:11})}>{m.comentario||""}</td>
                      </tr>
                    );})}
                  </tbody>
                </table>
                <div style={{padding:"10px 16px",borderTop:"1px solid #2a2010",color:"#5a4a2a",fontSize:11}}>Mostrando {movsF.length} de {movs.length} movimientos · tiempo real ⚡</div>
              </div>
            )}
          </div>
        )}

        {tab==="arqueos"&&(
          <div>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:20}}>
              <div>
                <div style={{fontSize:18,color:"#d4a843"}}>Arqueos Mensuales</div>
                <div style={{fontSize:12,color:"#5a4a2a",marginTop:3}}>Snapshot guardado en Supabase ⚡</div>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:12}}>
                {msg&&<span style={{color:"#7ec87e",fontSize:13}}>{msg}</span>}
                <button onClick={handleArqueo} style={{background:"#2a1f08",border:"1px solid #d4a843",color:"#d4a843",padding:"9px 20px",borderRadius:8,fontSize:13,cursor:"pointer"}}>📸 Hacer Arqueo Ahora</button>
              </div>
            </div>

            {ldArqs?<div style={{textAlign:"center",padding:60,color:"#8b7c4a"}}>Cargando... ⚡</div>:(
              <>
                <div style={{...tbl,marginBottom:20,padding:20}}>
                  <div style={{fontSize:12,color:"#8b7c4a",marginBottom:14,textTransform:"uppercase",letterSpacing:"0.07em"}}>Evolución patrimonial</div>
                  {arqs.length===0?<div style={{textAlign:"center",padding:40,color:"#5a4a2a"}}>No hay arqueos. Hacé el primero →</div>:(
                    <ResponsiveContainer width="100%" height={220}>
                      <AreaChart data={arqs}>
                        <defs>
                          <linearGradient id="g2" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#d4a843" stopOpacity={0.25}/><stop offset="95%" stopColor="#d4a843" stopOpacity={0}/></linearGradient>
                          <linearGradient id="g3" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#7ec87e" stopOpacity={0.25}/><stop offset="95%" stopColor="#7ec87e" stopOpacity={0}/></linearGradient>
                        </defs>
                        <CartesianGrid strokeDasharray="3 3" stroke="#2a2010"/>
                        <XAxis dataKey="mes" tick={{fill:"#5a4a2a",fontSize:9}}/>
                        <YAxis tick={{fill:"#5a4a2a",fontSize:9}} tickFormatter={v=>`$${(v/1000).toFixed(0)}k`}/>
                        <Tooltip contentStyle={{background:"#1a1408",border:"1px solid #3a3010",borderRadius:8}} formatter={v=>[f$(v),""]}/>
                        <Area type="monotone" dataKey="patrimonio" stroke="#d4a843" fill="url(#g2)" strokeWidth={2} name="Patrimonio"/>
                        <Area type="monotone" dataKey="resultado" stroke="#7ec87e" fill="url(#g3)" strokeWidth={2} name="Resultado"/>
                      </AreaChart>
                    </ResponsiveContainer>
                  )}
                </div>
                <div style={tbl}>
                  <table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}>
                    <thead><tr style={{background:"#1a1408"}}>{["Mes","Patrimonio Total","Efectivo","Invertido","Resultado","Variación"].map(h=><th key={h} style={TH}>{h}</th>)}</tr></thead>
                    <tbody>
                      {arqs.length===0?<tr><td colSpan={6} style={{textAlign:"center",padding:40,color:"#5a4a2a"}}>No hay arqueos.</td></tr>:
                      [...arqs].reverse().map((a,i,arr)=>{const prev=arr[i+1];const v=prev?((a.patrimonio-prev.patrimonio)/prev.patrimonio*100):null;return(
                        <tr key={a.id||i} style={{borderBottom:"1px solid #1a1408",background:i%2===0?"transparent":"#0f0d04"}}>
                          <td style={TD({color:"#d4a843",fontWeight:"bold"})}>{a.mes}</td>
                          <td style={TD({color:"#f0e6c8",fontWeight:"bold"})}>{f$(a.patrimonio)}</td>
                          <td style={TD()}>{f$(a.saldo_efectivo)}</td>
                          <td style={TD()}>{f$(a.invertido)}</td>
                          <td style={TD({color:"#7ec87e"})}>{f$(a.resultado)}</td>
                          <td style={TD({color:v===null?"#5a4a2a":v>=0?"#7ec87e":"#e87c7c"})}>{v===null?"—":`${v>=0?"+":""}${v.toFixed(2)}%`}</td>
                        </tr>
                      );})}
                    </tbody>
                  </table>
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
